function wholesale_public_row(array $row):array{return ['id'=>(string)$row['public_id'],'businessName'=>(string)$row['business_name'],'contactName'=>(string)$row['contact_name'],'email'=>(string)$row['email'],'phone'=>(string)($row['phone']??''),'website'=>(string)($row['website']??''),'businessType'=>(string)($row['business_type']??''),'location'=>(string)($row['location_text']??''),'estimatedMonthlyVolume'=>(string)($row['estimated_monthly_volume']??''),'orderFrequency'=>(string)($row['order_frequency']??''),'packageSizes'=>json_decode((string)($row['package_sizes_json']??'[]'),true)?:[],'flavorsInterest'=>(string)($row['flavors_interest']??''),'privateLabelInterest'=>(bool)$row['private_label_interest'],'freezerCapacity'=>(string)($row['freezer_capacity']??''),'fulfillmentPreference'=>(string)($row['fulfillment_preference']??''),'desiredStartDate'=>$row['desired_start_date'],'currentSupplier'=>(string)($row['current_supplier']??''),'notes'=>(string)($row['notes']??''),'stage'=>(string)$row['pipeline_stage'],'estimatedValue'=>$row['estimated_value']!==null?(float)$row['estimated_value']:null,'probability'=>(int)$row['probability_percent'],'assignedTo'=>$row['assigned_to']!==null?(int)$row['assigned_to']:null,'assignedName'=>(string)($row['assigned_name']??''),'nextFollowupAt'=>$row['next_followup_at'],'lastContactAt'=>$row['last_contact_at'],'lossReason'=>(string)($row['loss_reason']??''),'source'=>(string)$row['source'],'createdAt'=>$row['created_at'],'updatedAt'=>$row['updated_at']];}
if($_SERVER['REQUEST_METHOD']==='GET'){$action=(string)($_GET['action']??'list');if($action==='list'){$q=trim((string)($_GET['q']??''));$stage=trim((string)($_GET['stage']??''));$params=[$organizationId];$where='l.organization_id=? AND l.archived_at IS NULL';if($stage!==''&&in_array($stage,$stages,true)){$where.=' AND l.pipeline_stage=?';$params[]=$stage;}if($q!==''){$where.=' AND (l.business_name LIKE ? OR l.contact_name LIKE ? OR l.email LIKE ? OR l.flavors_interest LIKE ? OR l.notes LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like,$like);}$statement=$pdo->prepare("SELECT l.*,u.display_name AS assigned_name FROM wholesale_leads l LEFT JOIN users u ON u.id=l.assigned_to WHERE {$where} ORDER BY FIELD(l.pipeline_stage,'new','qualified','sample','quoted','negotiation','won','lost'),l.updated_at DESC LIMIT 250");$statement->execute($params);app_json_response(['ok'=>true,'stages'=>$stages,'leads'=>array_map('wholesale_public_row',$statement->fetchAll())]);}if($action==='detail'){$id=trim((string)($_GET['id']??''));$statement=$pdo->prepare("SELECT l.*,u.display_name AS assigned_name FROM wholesale_leads l LEFT JOIN users u ON u.id=l.assigned_to WHERE l.organization_id=? AND l.public_id=? AND l.archived_at IS NULL LIMIT 1");$statement->execute([$organizationId,$id]);$row=$statement->fetch();if(!$row)app_json_response(['ok'=>false,'message'=>'Wholesale lead not found.'],404);$activities=$pdo->prepare("SELECT a.*,u.display_name AS createdByName FROM wholesale_lead_activities a LEFT JOIN users u ON u.id=a.created_by WHERE a.organization_id=? AND a.wholesale_lead_id=? ORDER BY a.created_at DESC,a.id DESC LIMIT 100");$activities->execute([$organizationId,(int)$row['id']]);app_json_response(['ok'=>true,'lead'=>wholesale_public_row($row),'activities'=>$activities->fetchAll()]);}if($action==='summary'){$users=$pdo->prepare("SELECT DISTINCT u.id,u.display_name FROM users u INNER JOIN organization_memberships om ON om.user_id=u.id AND om.organization_id=? WHERE 