if($_SERVER['REQUEST_METHOD']!=='POST'){header('Allow: GET, POST');app_json_response(['ok'=>false,'message'=>'Method not allowed.'],405);}$input=app_json_input();app_verify_request_csrf($input);$action=(string)($input['action']??'');$publicId=trim((string)($input['id']??''));$statement=$pdo->prepare('SELECT * FROM wholesale_leads WHERE organization_id=? AND public_id=? AND archived_at IS NULL LIMIT 1');$statement->execute([$organizationId,$publicId]);$lead=$statement->fetch();if(!$lead)app_json_response(['ok'=>false,'message'=>'Wholesale lead not found.'],404);$leadId=(int)$lead['id'];
if($action==='stage'){$stage=(string)($input['stage']??'');if(!in_array($stage,$stages,true))app_json_response(['ok'=>false,'message'=>'Invalid wholesale stage.'],422);$probMap=['new'=>10,'qualified'=>30,'sample'=>45,'quoted'=>60,'negotiation'=>75,'won'=>100,'lost'=>0];$update=$pdo->prepare("UPDATE wholesale_leads SET pipeline_stage=?,probability_percent=?,won_at=IF(?='won',COALESCE(won_at,NOW(6)),NULL),lost_at=IF(?='lost',COALESCE(lost_at,NOW(6)),NULL),updated_at=NOW(6) WHERE id=? AND organization_id=?");$update->execute([$stage,$probMap[$stage],$stage,$stage,$leadId,$organizationId]);$activity=$pdo->prepare("INSERT INTO wholesale_lead_activities (organization_id,wholesale_lead_id,activity_type,summary,created_by) VALUES (?,?,'stage',?,?)");$activity->execute([$organizationId,$leadId,'Pipeline moved from '.$lead['pipeline_stage'].' to '.$stage,(int)$user['id']]);restaurant_brain_sync_wholesale($pdo,$organizationId,$leadId,(int)$user['id']);app_audit($pdo,$organizationId,(int)$user['id'],'wholesale.stage_changed','wholesale_lead',$publicId,['stage'=>$lead['pipeline_stage']],['stage'=>$stage]);app_json_response(['ok'=>true,'message'=>'Wholesale stage updated.']);}
if($action==='update'){$estimatedValue=$input['estimatedValue']??null;if($estimatedValue!==null&&$estimatedValue!==''&&!is_numeric($estimatedValue))app_json_response(['ok'=>false,'message'=>'Estimated value must be numeric.'],422);$probability=max(0,min(100,(int)($input['probability']??$lead['probability_percent'])));$assignedTo=isset($input['assignedTo'])&&$input['assignedTo']!==''?(int)$input['assignedTo']:null;$nextFollowup=trim((string)($input['nextFollowupAt']??''));if($nextFollowup!==''){$dt=DateTimeImmutable::createFromFormat('Y-m-d\TH:i',$nextFollowup);if(!$dt)app_json_response(['ok'=>false,'message'=>'Follow-up date is invalid.'],422);$nextFollowup=$dt->format('Y-m-d H:i:s');}else $nextFollowup=null;$notes=mb_substr(trim((string)($input['notes']??$lead['notes']??'')),0,10000,'UTF-8');$lossReason=mb_substr(trim((string)($input['lossReason']??$lead['loss_reason']??'')),0,500,'UTF-8');if($assignedTo){$check=$pdo->prepare("SELECT COUNT(*) FROM users u INNER JOIN organization_memberships om ON om.user_id=u.id WHERE u.id=? AND om.organization_id=? AND u.status='active' AND u.archived_at IS NULL");$check->execute([$assignedTo,$organizationId]);if(!(int)$check->fetchColumn())app_json_response(['ok'=>false,'message'=>'Assignee is not an active organization user.'],422);}$update=$pdo->prepare("UPDATE wholesale_leads SET estimated_value=?,probability_percent=?,assigned_to=?,next_followup_at=?,notes=?,loss_reason=?,updated_at=NOW(6) WHERE id=? AND organization_id=?");$update->execute([$estimatedValue===''?null:$estimatedValue,$probability,$assignedTo,$nextFollowup,$notes?:null,$lossReason?:null,$leadId,$organizationId]);restaurant_brain_sync_wholesale($pdo,$organizationId,$leadId,(int)$user['id']);app_audit($pdo,$organizationId,(int)$user['id'],'wholesale.updated','wholesale_lead',$publicId,null,['estimatedValue'=>$estimatedValue,'probability'=>$probability,'assignedTo'=>$assignedTo,'nextFollowupAt'=>$nextFollowup]);app_json_response(['ok'=>true,'message'=>'Wholesale lead updated.']);}
if($action==='activity'){$type=trim((string)($input['activityType']??'note'));$allowed=['note','call','email','meeting','sample','quote','followup'];if(!in_array($type,$allowed,true))$type='note';$summary=mb_substr(trim((string)($input['summary']??'')),0,500,'UTF-8');$details=mb_substr(trim((string)($input['details']??'')),0,10000,'UTF-8');if($summary==='')app_json_response(['ok'=>false,'message'=>'Enter an activity summary.'],422);$insert=$pdo->prepare("INSERT INTO wholesale_lead_activities (organization_id,wholesale_lead_id,activity_type,summary,details,created_by) VALUES (?,?,?,?,?,?)");$insert->execute([$organizationId,$leadId,$type,$summary,$details?:null,(int)$user['id']]);$pdo->prepare('UPDATE wholesale_leads SET last_contact_at=NOW(6),updated_at=NOW(6) WHERE id=? AND organization_id=?')->execute([$leadId,$organizationId]);restaurant_brain_sync_wholesale($pdo,$organizationId,$leadId,(int)$user['id']);app_audit($pdo,$organizationId,(int)$user['id'],'wholesale.activity_added','wholesale_lead',$publicId,null,['activityType'=>$type,'summary'=>$summary]);app_json_response(['ok'=>true,'message'=>'Wholesale activity added.']);}
